54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Dedicated audit logger for owner lifecycle side-effects. */
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    /**
67	     * Pragmatic check for a syntactically valid email address: a non-empty local
68	     * part, a single '@', and a domain with at least one dot-separated label.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization,
75	     * keyed by their upper-cased form.
76	     */
77	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
78	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
126	        // Validate & normalize the optional email; reject the create when it is present but invalid.
127	        if (!normalizeEmail(ownerFieldsDto)) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
131	        // abbreviations) and store the normalized form back on the DTO so it is what gets
132	        // persisted and compared. Reject the create when the address is blank once normalized.
133	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        if (canonicalAddress.isBlank()) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        ownerFieldsDto.setAddress(canonicalAddress);
138	        // Reject the create when the owner's city is already at capacity, i.e. it already
139	        // contains 50 or more owners (compared case-insensitively).
140	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
144	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
145	        if (normalizedTelephone == null) {
146	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
147	        }
148	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
149	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
150	            .map(Owner::getTelephone)
151	            .map(OwnerRestControllerV1::toE164)
152	            .filter(existing -> existing != null)
153	            .anyMatch(normalizedTelephone::equals);
154	        if (telephoneInUse) {
155	            return new ResponseEntity<>(HttpStatus.CONFLICT);
156	        }
157	        // Reject the create when another owner already shares this owner's last name and address
158	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
159	        // sharing a household.
160	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
161	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
162	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
163	            boolean householdInUse = this.clinicService.findAllOwners().stream()
164	                .anyMatch(existing ->
165	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
166	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
167	            if (householdInUse) {
168	                return new ResponseEntity<>(HttpStatus.CONFLICT);
169	            }
170	        }
171	        // Determine the effective registration date — the value supplied on the request, or the
172	        // server's current date when none was supplied — and roll it forward to the next business
173	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
174	        // registration date (membership-number year segment, per-day create-limit) uses this
175	        // adjusted date.
176	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
177	        if (registrationDate == null) {
178	            registrationDate = LocalDate.now();
179	        }
180	        registrationDate = toBusinessDay(registrationDate);
181	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
182	        // owners have already been registered on this (adjusted) business day.
183	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
184	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
185	        }
186	        ownerFieldsDto.setTelephone(normalizedTelephone);
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        owner.setRegistrationDate(registrationDate);
190	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
191	        // letters of the city, the upper-cased first three letters of the last name, and a
192	        // per-city 4-digit sequence one greater than the number of owners already in that city.
193	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
194	        // Record how many existing owners already share this owner's first and last name
195	        // (compared case-insensitively) at the moment before this owner is created.
196	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
198	        // registered on this (adjusted) business day before this owner is created.
199	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
200	        // Record the size of this owner's household after this create: the number of existing
201	        // owners sharing the same household (matching last name and address) plus this owner.
202	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
203	        this.clinicService.saveOwner(owner);
204	        // Emit an audit line recording the new owner's id, customer code, registration date
205	        // and membership level.
206	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
207	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
208	            ownerMapper.membershipLevel(owner));
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
210	        headers.setLocation(UriComponentsBuilder.newInstance()
211	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
212	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
213	    }
214	
215	    /**
216	     * Validate and normalize the optional owner email in place.
217	     *
218	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
219	     * When present it must be a syntactically valid address; a valid address is
220	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
221	     * present but syntactically invalid, so the caller can reject with 400.
222	     */
223	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
224	        String email = ownerFieldsDto.getEmail();
225	        if (email == null || email.isBlank()) {
226	            ownerFieldsDto.setEmail(null);
227	            return true;
228	        }
229	        String normalized = email.trim().toLowerCase(Locale.ROOT);
230	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
231	            return false;
232	        }
233	        ownerFieldsDto.setEmail(normalized);
234	        return true;
235	    }
236	
237	    /**
238	     * Normalize an owner address: trim, collapse each run of whitespace to a single
239	     * space, upper-case, and expand common street-type abbreviations
240	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
241	     * A {@code null} value normalizes to the empty string.
242	     */
243	    private static String normalizeAddress(String value) {
244	        if (value == null) {
245	            return "";
246	        }
247	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
248	        if (collapsed.isEmpty()) {
249	            return "";
250	        }
251	        String[] tokens = collapsed.split(" ");
252	        StringBuilder sb = new StringBuilder(collapsed.length());
253	        for (int i = 0; i < tokens.length; i++) {
254	            if (i > 0) {
255	                sb.append(' ');
256	            }
257	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
258	        }
259	        return sb.toString();
260	    }
261	
262	    /**
263	     * Normalize an owner household field (last name or address) for duplicate detection:
264	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
265	     * A {@code null} value normalizes to the empty string.
266	     */
267	    private static String normalizeHouseholdKey(String value) {
268	        if (value == null) {
269	            return "";
270	        }
271	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
272	    }
273	
274	    /**
275	     * Normalize a telephone number to E.164 form.
276	     *
277	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
278	     * explicit leading {@code '+'} and country code it is kept; otherwise the
279	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
280	     * dropped from the national digits. The result must contain 8 to 15 digits
281	     * after the {@code '+'}.
282	     *
283	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
284	     *         the input is absent or cannot form a valid E.164 number.
285	     */
286	    private static String toE164(String raw) {
287	        if (raw == null) {
288	            return null;
289	        }
290	        String trimmed = raw.trim();
291	        boolean hasCountryCode = trimmed.startsWith("+");
292	        // Strip spaces, dashes and brackets.
293	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
294	        String digits;
295	        if (hasCountryCode) {
296	            // Keep the explicit country code; drop the leading '+' for validation.
297	            digits = stripped.substring(1);
298	        } else {
299	            // No country code: assume '+61' and drop a single leading '0'.
300	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
301	            digits = "61" + national;
302	        }
303	        if (!digits.matches("\\d{8,15}")) {
304	            return null;
305	        }
306	        return "+" + digits;
307	    }
308	
309	    /**
310	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
311	     *
312	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
313	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
314	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
315	     * equal to one more than the number of owners already in that city
316	     * (e.g. {@code 'SYD-SMI-0007'}).
317	     */
318	    /**
319	     * Count the existing owners whose first and last name match the given names,
320	     * compared case-insensitively. Used to record an owner's namesake count at the
321	     * moment before it is created.
322	     */
323	    private int countNamesakes(String firstName, String lastName) {
324	        return (int) this.clinicService.findAllOwners().stream()
325	            .filter(existing -> existing.getFirstName() != null
326	                && existing.getFirstName().equalsIgnoreCase(firstName)
327	                && existing.getLastName() != null
328	                && existing.getLastName().equalsIgnoreCase(lastName))
329	            .count();
330	    }
331	
332	    /**
333	     * Count the existing owners in the same household as the given last name and address
334	     * (compared after household-key normalization). Used, together with the owner being
335	     * created, to derive the household size recorded on the owner.
336	     */
337	    private int countHouseholdMembers(String lastName, String address) {
338	        String normalizedLastName = normalizeHouseholdKey(lastName);
339	        String normalizedAddress = normalizeHouseholdKey(address);
340	        return (int) this.clinicService.findAllOwners().stream()
341	            .filter(existing ->
342	                normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
343	                    && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress))
344	            .count();
345	    }
346	
347	    private String nextCustomerCode(String city, String lastName) {
348	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
349	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
350	        int sequence = countOwnersInCity(city) + 1;
351	        return String.format("%s-%s-%04d", city3, last3, sequence);
352	    }
353	
354	    /**
355	     * Count the existing owners located in the given city, compared case-insensitively.
356	     * Used to derive the per-city 4-digit sequence in the customer code.
357	     */
358	    private int countOwnersInCity(String city) {
359	        return (int) this.clinicService.findAllOwners().stream()
360	            .filter(existing -> existing.getCity() != null
361	                && existing.getCity().equalsIgnoreCase(city))
362	            .count();
363	    }
364	
365	    /**
366	     * Count the existing owners whose registration date is the given (adjusted business) date.
367	     * Used to enforce the per-day sign-up limit.
368	     */
369	    private int countOwnersRegisteredOn(LocalDate date) {
370	        return (int) this.clinicService.findAllOwners().stream()
371	            .filter(existing -> date.equals(existing.getRegistrationDate()))
372	            .count();
373	    }
374	
375	    /**
376	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
377	     * the following Monday; a weekday is returned unchanged.
378	     */
379	    private static LocalDate toBusinessDay(LocalDate date) {
380	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
381	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
382	            date = date.plusDays(1);
383	        }
384	        return date;
385	    }
386	
387	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
388	    @Override
389	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
390	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
391	        if (currentOwner == null) {
392	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
393	        }
394	        if (!normalizeEmail(ownerFieldsDto)) {
395	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
396	        }
397	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
398	        if (normalizedTelephone == null) {
399	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
400	        }
401	        currentOwner.setAddress(ownerFieldsDto.getAddress());
402	        currentOwner.setCity(ownerFieldsDto.getCity());
403	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
404	        currentOwner.setLastName(ownerFieldsDto.getLastName());
405	        currentOwner.setTelephone(normalizedTelephone);
406	        currentOwner.setEmail(ownerFieldsDto.getEmail());
407	        this.clinicService.saveOwner(currentOwner);
408	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
409	    }
410	
411	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
412	    @Transactional
413	    @Override
414	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
415	        Owner owner = this.clinicService.findOwnerById(ownerId);
416	        if (owner == null) {
417	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
418	        }
419	        this.clinicService.deleteOwner(owner);
420	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
421	    }
422	
423	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
424	    @Override
425	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
426	        Owner owner = this.clinicService.findOwnerById(ownerId);
427	        if (owner == null) {
428	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
429	        }
430	        HttpHeaders headers = new HttpHeaders();
431	        Pet pet = petMapper.toPet(petFieldsDto);
432	        owner.setId(ownerId);
433	        pet.setOwner(owner);
434	        pet.getType().setName(null);
435	        this.clinicService.savePet(pet);
436	        PetDto petDto = petMapper.toPetDto(pet);
437	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
438	            .buildAndExpand(pet.getId()).toUri());
439	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
440	    }
441	
442	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
443	    @Override
444	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
445	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
446	        if (currentOwner != null) {
447	            Pet currentPet = this.clinicService.findPetById(petId);
448	            if (currentPet != null) {
449	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
450	                currentPet.setName(petFieldsDto.getName());
451	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
452	                this.clinicService.savePet(currentPet);
453	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
454	            }
455	        }
456	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
457	    }
458	
459	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
460	    @Override
461	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
462	        HttpHeaders headers = new HttpHeaders();
463	        Visit visit = visitMapper.toVisit(visitFieldsDto);
464	        Pet pet = new Pet();
465	        pet.setId(petId);
466	        visit.setPet(pet);
467	        this.clinicService.saveVisit(visit);
468	        VisitDto visitDto = visitMapper.toVisitDto(visit);
469	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
470	            .buildAndExpand(visit.getId()).toUri());
471	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
472	    }
473	
474	
475	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
476	    @Override
477	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
478	        Owner owner = this.clinicService.findOwnerById(ownerId);
479	        if (owner != null) {
480	            Pet pet = owner.getPet(petId);
481	            if (pet != null) {
482	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
483	            }
484	        }
485	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
486	    }
487	}
